<section class="faq-section section light" aria-labelledby="faq-title"><div class="container faq-layout"><div><p class="eyebrow"><?php rzz_text('faq_label','Frequently asked questions'); ?></p><h2 id="faq-title"><?php rzz_text('faq_title','A little clarity, before we begin.'); ?></h2><a class="text-link" href="<?php echo esc_url(rzz_link('contact')); ?>">Talk to our team <?php echo rzz_arrow(); ?></a></div><div class="faq-list"><?php foreach(rzz_faqs() as $i=>$item):$question=rzz_setting('faq_q_'.$i,$item[0]);$answer=rzz_setting('faq_a_'.$i,$item[1]);if(!$question||!$answer)continue; ?><details><summary><?php echo esc_html($question); ?><span aria-hidden="true">+</span></summary><p><?php echo esc_html($answer); ?></p></details><?php endforeach; ?></div></div></section>